Output221[Better Approach] Using Stack - O(n) Time and O(n) SpaceWe use a stack to build the smallest number by maintaining digits in increasing order. For each digit, we remove up to k larger digits from the stack before pushing the current one. This ensures smaller digits appear earlier while preserving the original order.Illustration of the example using stack based approach:Below is the implementation of the above approach.
            C++

    #include <iostream>
#include <stack>
using namespace std;

string removeKdig(string &s, int k) {
    int n = s.size();
    stack<char> st;

    for (int i = 0; i < s.size(); ++i) {
        char c = s[i];

        // Remove larger digits when possible
        while (!st.empty() && k > 0 && st.top() > c) {
            st.pop();
            k -= 1;
        }

        if (!st.empty() || c != '0')
            st.push(c);
    }

    // Remove remaining digits if any
    while (!st.empty() && k--)
        st.pop();

    if (st.empty())
        return "0";

    // Build result from stack
    while (!st.empty()) {
        s[n - 1] = st.top();
        st.pop();
        n -= 1;
    }

    return s.substr(n);
}

int main() {
    string s = "765028321";
    int k = 5;
    cout << removeKdig(s, k);
    return 0;
}


