Output221[Expected Approach] In-Place Digit Removal - O(n) Time and O(1) SpaceWe treat the input string as a stack using a pointer top. For each digit, we overwrite the previous digits if they are larger and we still have digits to remove (k > 0). This builds the smallest number in-place while avoiding extra memory. Remaining digits are trimmed from the end, and leading zeros are skipped.
            C++

    #include <iostream>
using namespace std;

string removeKdig(string &s, int k) {
    int n = s.size();
    int top = 0; // acts like a stack pointer

    for (int i = 0; i < n; ++i) {
        char c = s[i];

        // Remove larger digits when possible (up to k digits)
        while (top > 0 && k > 0 && s[top - 1] > c) {
            top--;
            k--;
        }

        // Avoid leading zeros
        if (top > 0 || c != '0')
            s[top++] = c;
    }

    // Remove remaining digits if any
    top = max(0, top - k);

    if (top == 0)
        return "0";

    // Build result from the string itself
    return s.substr(0, top);
}

int main() {
    string s = "765028321";
    int k = 5;
    cout << removeKdig(s, k);
    return 0;
}


